import{_ as n,C as s,c as l,o as u,ag as a,j as t,G as i,a as r}from"./chunks/framework.Bw-5EFTY.js";const b=JSON.parse('{"title":"Onboarding Setup","description":"","frontmatter":{},"headers":[],"relativePath":"guide/getting-started/onboarding-setup.md","filePath":"guide/getting-started/onboarding-setup.md","lastUpdated":1752213781000}'),p={name:"guide/getting-started/onboarding-setup.md"};function g(d,e,f,c,h,m){const o=s("ZoomableImage");return u(),l("div",null,[e[0]||(e[0]=a('<h1 id="onboarding-setup" tabindex="-1">Onboarding Setup <a class="header-anchor" href="#onboarding-setup" aria-label="Permalink to &quot;Onboarding Setup&quot;">​</a></h1><p>So, you&#39;ve just installed FluentAffiliate. Welcome! The first thing you&#39;ll see is our quick <strong>Onboarding</strong> setup, designed to guide you through the core settings to get your affiliate program up and running in minutes.</p><p>The best part? You&#39;re always in control. If you&#39;re not ready to configure everything right away, you can skip steps and revisit them later from the main settings panel.</p><p>Let&#39;s walk through the new onboarding setup, step by step.</p><h2 id="step-1-connect-your-plugins" tabindex="-1">Step 1: Connect Your Plugins <a class="header-anchor" href="#step-1-connect-your-plugins" aria-label="Permalink to &quot;Step 1: Connect Your Plugins&quot;">​</a></h2><p>The first step helps FluentAffiliate understand which platforms you use to sell products, courses, or services.</p><ul><li><strong>Choose your plugin to get started:</strong> In this list, simply check the boxes next to the plugins you have installed and plan to use with your affiliate programs, such as FluentForms, WooCommerce, or LearnDash etc.</li></ul><p>Click the <strong>Next</strong> button to proceed.</p>',8)),t("p",null,[i(o,{src:"/guide/public/images/getting-started/onboarding-setup/onboarding-fluentaffiliate-1.webp",alt:"Connecting integration plugins during FluentAffiliate onboarding"})]),e[1]||(e[1]=a('<h2 id="step-2-set-your-default-commission" tabindex="-1">Step 2: Set Your Default Commission <a class="header-anchor" href="#step-2-set-your-default-commission" aria-label="Permalink to &quot;Step 2: Set Your Default Commission&quot;">​</a></h2><p>In this step, you&#39;ll set the default referral and commission structure for your entire affiliate program. These are the global settings that will apply unless you create custom rates for specific products.</p><p>Here’s what to fill out:</p><ul><li><strong>Referral Variable:</strong> This is the keyword that will appear in your affiliate URLs. For example, if you set it as <code>ref</code>, a referral link will look like <code>yoursite.com/?ref=username</code>.</li><li><strong>Default Referral Format:</strong> Choose whether your affiliate links will use the affiliate&#39;s numeric ID or WordPress Username. Both options track perfectly; just pick the one you prefer.</li><li><strong>Rate:</strong> Enter the default commission value your affiliates will earn. You can also choose if this rate is a <strong>Percentage (%)</strong> of the sale or a <strong>Fixed</strong> amount.</li><li><strong>Default Currency:</strong> Select the currency you will use to pay your affiliate commissions from the dropdown menu.</li></ul><p>Once you&#39;ve configured these settings, click <strong>Next</strong>.</p>',5)),t("p",null,[i(o,{src:"/guide/public/images/getting-started/onboarding-setup/onboarding-fluentaffiliate-2.webp",alt:"Commission Setup in FluentAffiliate"})]),e[2]||(e[2]=a('<h2 id="step-3-create-your-affiliate-portal" tabindex="-1">Step 3: Create Your Affiliate Portal <a class="header-anchor" href="#step-3-create-your-affiliate-portal" aria-label="Permalink to &quot;Step 3: Create Your Affiliate Portal&quot;">​</a></h2><p>The final step is to create a dedicated page for your affiliates. This &quot;Affiliate Portal&quot; is where they will log in, track their performance, and generate their unique promotional links.</p><ul><li><p><strong>Affiliate Area:</strong> You need to select a page to serve as the portal. You can either choose an existing page from the dropdown menu or click the <strong>plus (+)</strong> icon to create a new page instantly.</p></li><li><p>If you create a new page, a pop-up will appear where you can enter the <strong>Page Title</strong> (e.g., &quot;Affiliate Area&quot;) and click <strong>Add</strong> button.</p></li></ul><p>FluentAffiliate will automatically place the <code>[fluent_affiliate_portal]</code> shortcode on the page you select. This shortcode is what makes the affiliate dashboard appear.</p>',4)),t("p",null,[i(o,{src:"/guide/public/images/getting-started/onboarding-setup/onboarding-fluentaffiliate-3.webp",alt:"Creating the Affiliate Portal page during onboarding"})]),e[3]||(e[3]=t("p",null,[r("When you're ready, click the "),t("strong",null,"Finish"),r(" button to save your settings and complete the setup.")],-1)),e[4]||(e[4]=t("p",null,"That's it, you're all set with the onboarding setup for Fluent Affiliate!",-1))])}const _=n(p,[["render",g]]);export{b as __pageData,_ as default};
